Bytes shell() { return data_shell(); }
Bytes library(const std::string& abi) {
if (abi == "armeabi-v7a") return data_armeabi_v7a();
if (abi == "arm64-v8a") return data_arm64_v8a();
if (abi == "x86") return data_x86();
if (abi == "x86_64") return data_x86_64();
throw std::runtime_error("Unsupported Shield ABI.");
}
